export default async function next({ body, acknowledgeOrderId, harvestClientId, coupon }, ctx) {
  const none = {
    more: false,
    order: {},
    invoice: {},
    cardName: "unused",
    attachmentUrl: "https://example.com",
    email: "",
    message: "",
    high: false,
    contact: {},
  };
  if (!body?.customer || !body?.shipping_address)
    throw Error("Expected a complete Shopify order with customer and shipping address");
  const id =
    typeof body.admin_graphql_api_id === "string" && body.admin_graphql_api_id
      ? body.admin_graphql_api_id
      : Number.isSafeInteger(body.id)
        ? String(body.id)
        : null;
  if (!id) throw Error("Order requires its full Shopify GraphQL ID");
  const s = (await ctx.state.get("shopify-order-tasks")) ?? { queue: [], pending: null, done: [] };
  if (!s.done.includes(id) && s.pending?.id !== id && !s.queue.some((x) => x.id === id)) {
    s.queue.push({ id, body });
    await ctx.state.set("shopify-order-tasks", s);
  }
  if (s.pending) {
    if (acknowledgeOrderId !== s.pending.id)
      throw Error("Inspect and complete pending order " + s.pending.id + " at " + s.pending.stage);
    s.done.push(s.pending.id);
    s.pending = null;
    await ctx.state.set("shopify-order-tasks", s);
  }
  if (!s.queue.length) return none;
  const item = s.queue.shift(),
    o = item.body,
    c = o.customer,
    a = o.shipping_address,
    total = Number(o.current_total_price);
  if (
    !Number.isSafeInteger(harvestClientId) ||
    harvestClientId <= 0 ||
    !Number.isFinite(total) ||
    typeof c.email !== "string" ||
    !c.email ||
    typeof c.last_name !== "string" ||
    !c.last_name ||
    !o.order_status_url ||
    !o.currency ||
    !o.processed_at
  )
    throw Error("Configure Harvest client and provide required Shopify order fields");
  const high = total > 50;
  if (high && (!coupon || coupon.startsWith("YOUR_")))
    throw Error("Configure coupon code for high-value orders");
  s.pending = { id: item.id, stage: "harvest invoice" };
  await ctx.state.set("shopify-order-tasks", s);
  const name = c.first_name ?? "",
    message = high
      ? `Hi ${name},\n\nThank you for your order! Here's a 15% coupon code to use for your next order: ${coupon}\n\nBest,\nShop Owner`
      : `Hi ${name},\nThank you for your order! We're getting it ready for shipping it to you.\n\nBest,\nShop Owner`;
  return {
    more: true,
    order: { id: item.id },
    invoice: {
      client_id: harvestClientId,
      currency: o.currency,
      issue_date: o.processed_at.slice(0, 10),
      payment_term: "net 15",
      purchase_order: String(o.order_number),
    },
    cardName: "Shopify order " + o.order_number,
    attachmentUrl: o.order_status_url,
    email: c.email,
    message,
    high,
    contact: {
      Last_Name: c.last_name,
      First_Name: name,
      Email: c.email,
      Phone: String(c.default_address?.phone ?? ""),
      Mailing_Zip: String(a.zip ?? ""),
      Mailing_City: a.city ?? "",
      Mailing_State: a.province ?? "",
      Mailing_Street: a.address1 ?? "",
      Mailing_Country: a.country ?? "",
    },
  };
}

