export default async function stage({ order, stage, result, expect }, ctx) {
  const ok =
    expect === "invoice"
      ? Number.isSafeInteger(result?.id)
      : expect === "card" || expect === "attachment"
        ? typeof result?.id === "string" && !!result.id
        : expect === "contact"
          ? result?.data?.[0]?.status === "success"
          : expect === "email"
            ? typeof result === "string" && !!result
            : expect === "tag"
              ? result === true
              : false;
  if (!ok) throw Error("Previous operation not confirmed");
  const s = await ctx.state.get("shopify-order-tasks");
  if (s?.pending?.id !== order.id) throw Error("Pending order mismatch");
  s.pending.stage = stage;
  await ctx.state.set("shopify-order-tasks", s);
  return { ready: true, id: typeof result?.id === "string" ? result.id : "unused" };
}

