export default async function finish({ order, result, expect }, ctx) {
  if (
    !(expect === "email"
      ? typeof result === "string" && !!result
      : expect === "tag"
        ? result === true
        : false)
  )
    throw Error("Previous operation not confirmed");
  const s = await ctx.state.get("shopify-order-tasks");
  if (s?.pending?.id !== order.id) throw Error("Pending order mismatch");
  s.done.push(order.id);
  s.pending = null;
  await ctx.state.set("shopify-order-tasks", s);
  return { done: true };
}

